  "canonical_text": {
    "quote": "",
    "summary": "The supplied passage explains Plate IV as a numbered catalog of facial painting designs from northern British Columbia. Each entry identifies a painted form as representing a body part or associated object of an animal or supernatural being, often gives its color and position on the face, and frequently names the group that uses the design.",
    "language": "English",
    "quote_policy": "summarized"
