  "passage_locator": {
    "label": "STORIES   OF  OLD  MAN / IV  CONTENTS / THE   STORY  OF  THE    THREE    TRIBES. / BLACKFOOT   LODGE   TALES; lines 220-279",
    "start": "220",
    "end": "279",
    "translation": "Blackfoot Lodge Tales",
    "notes": "Stable markdown line range generated from canonical text."
  },
  "canonical_text": {
    "quote": "",
    "summary": "After a contents list, the passage opens in a lodge at Two Medicine, where the narrator sits with Double Runner, Small Leggings, Mad Wolf, and the Little Blackfoot around the fire. Double Runner picks up a scrap of printed paper and says that literacy is a form of education that gives white people an advantage. The narrator replies that children should go to school because times have changed. Double Runner then says the old ways are passing away and that descendants will know them only through the things the men have told the narrator and that he has written down, including the story of the three tribes.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "The narrator and four named men sit in a lodge at Two Medicine around a fire, smoking and talking while the narrator writes in a notebook.",
      "category": "setting",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Double Runner picks up a scrap of printed paper from the ground, looks at it, holds it up, and speaks about it.",
      "category": "action",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "Double Runner says the narrator can understand the printed paper while he cannot, and says that if his people knew such things, white people would not always get the best of them.",
      "category": "speech",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:4",
      "text": "The narrator says Double Runner should have his children go to school so they can gain white people's knowledge, trade successfully, and live in changed times.",
      "category": "speech",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:5",
      "text": "Double Runner says the old things are passing away and that later generations will know former life only by reading what has been told to the narrator and written in his books.",
      "category": "speech",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:6",
      "text": "The narrator says the story of the three tribes, Sik-si-kau, Kainah, and Pikuni, has been written down.",
      "category": "speech",
      "evidence_refs": [
        "ev:6"
