  "literal_observations": [
    {
      "id": "obs:1",
      "text": "People find the man well in his own cave.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "The man asks for blue beads, native tobacco, a black silk handkerchief, and eagle feathers, and takes these presents by night to Scalped-Man's cave.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:3",
      "text": "During the Medicine-Men's ceremony, different medicine-men perform sleight-of-hand acts taught to them by different animals.",
      "category": "sequence",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:4",
      "text": "The man throws his voice in different directions so that many voices seem to be speaking though he is alone.",
      "category": "action",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:5",
      "text": "Some people call him the wonderful man, while others call him Scalped-Man because they heard he had been living with Scalped-Man.",
      "category": "speech",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:6",
      "text": "An enemy attacker is described as able to make arrows and blows miss him.",
      "category": "attribute",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:7",
      "text": "The wounded man covers his body with white clay, puts a downy feather in his hair, hangs an eagle-wing whistle around his neck, carries wild sage and a small war club, and runs out to fight.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:8",
      "text": "Arrows shot at the man go to the right and left of him, and he kills the powerful enemy with a blow from the small war club.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:9",
      "text": "After the enemy gives way, the man kills many attackers, returns to the medicine-lodge, and is later described as a great medicine-man and warrior who is never injured in battle.",
      "category": "sequence",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:10",
      "text": "After a long life, the man commits suicide because something tells him that his friend Scalped-Man is gone.",
      "category": "action",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:11",
      "text": "In the next narrative, a missing man returns during a buffalo hunt wearing a buffalo robe and soft eagle feathers, with a soft feather fixed in his scalp-lock.",
      "category": "attribute",
      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:12",
      "text": "The people regard the man's feathered appearance as a sign that he has been to some animals' lodge or other mysterious place.",
      "category": "speech",
      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:13",
      "text": "The feathered man sits alone on the south side and does not allow any other man to sit with him.",
      "category": "relationship",
      "evidence_refs": [
        "ev:8"
      ]
    },
    {
      "id": "obs:14",
      "text": "The feathered man disappears again and later returns with more eagle feathers tied in a small buffalo robe, which he hangs up in his tipi.",
      "category": "action",
      "evidence_refs": [
        "ev:9"
      ]
    }
